package main

import "fmt"

type Task struct {
	Name string
	Done bool
}

func main() {
	tasks := []Task{{Name: "test"}, {Name: "ship"}}
	for _, task := range tasks {
		task.Done = true
	}
	fmt.Println("after copied values:", tasks)

	for i := range tasks {
		tasks[i].Done = true
	}
	fmt.Println("after indexes:", tasks)

	pointed := []*Task{{Name: "review"}}
	for _, task := range pointed {
		task.Done = true
	}
	fmt.Println("after pointer:", *pointed[0])
}
