package main

import (
	"fmt"
	"sort"
)

func main() {
	scores := map[string]int{"Ada": 9, "Lin": 4, "Mina": 7}
	for name, score := range scores {
		if score < 6 {
			delete(scores, name)
		}
	}

	labels := make(map[string]int, len(scores))
	for name, score := range scores {
		labels["qualified:"+name] = score
	}

	keys := make([]string, 0, len(labels))
	for key := range labels {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	fmt.Println(keys)
}
