package main

import "fmt"

func main() {
	values := []int{1, 2}
	visits := make([]int, 0, len(values))
	for _, value := range values {
		visits = append(visits, value)
		values = append(values, value+10)
	}
	fmt.Println("range visits:", visits)
	fmt.Println("after range:", values)

	queue := []int{1, 2}
	for i := 0; i < len(queue); i++ {
		if queue[i] < 3 {
			queue = append(queue, queue[i]+2)
		}
	}
	fmt.Println("growing queue:", queue)
}
